CREATE TABLE guild_configs (guild_id text PRIMARY KEY, config jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_consents (guild_id text NOT NULL, user_id text NOT NULL, policy_version text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz, PRIMARY KEY(guild_id,user_id,policy_version));
CREATE TABLE occupancy_episodes (id uuid PRIMARY KEY, guild_id text NOT NULL, channel_id text NOT NULL, state text NOT NULL, body jsonb NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE UNIQUE INDEX episode_one_open ON occupancy_episodes(channel_id) WHERE closed_at IS NULL;
CREATE TABLE meetings (id uuid PRIMARY KEY, guild_id text NOT NULL, voice_channel_id text NOT NULL, record_channel_id text NOT NULL, controller_id text NOT NULL, status text NOT NULL, view jsonb NOT NULL, settings jsonb NOT NULL, owner text, fencing bigint NOT NULL DEFAULT 1, lease_until timestamptz, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), runtime jsonb NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX meeting_one_voice ON meetings(guild_id) WHERE status IN ('STARTING','RECORDING','PAUSED','DEGRADED','STOPPING') AND deleted_at IS NULL;
CREATE TABLE guild_leases (guild_id text PRIMARY KEY, fencing bigint NOT NULL DEFAULT 0);
CREATE TABLE meeting_event_counters (meeting_id uuid PRIMARY KEY REFERENCES meetings(id) ON DELETE CASCADE, last_seq bigint NOT NULL DEFAULT 0, floor_seq bigint NOT NULL DEFAULT 0);
CREATE TABLE meeting_events (meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, event_seq bigint NOT NULL, event jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(meeting_id,event_seq));
CREATE INDEX events_expiry ON meeting_events(created_at);
CREATE TABLE meeting_participants (meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, user_id text NOT NULL, body jsonb NOT NULL, intervals jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(meeting_id,user_id));
CREATE TABLE transcript_segments (segment_id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, user_id text NOT NULL, source_key text NOT NULL, raw_text text NOT NULL, body jsonb NOT NULL, canonical boolean NOT NULL DEFAULT true, source_start_ms integer NOT NULL, source_end_ms integer, UNIQUE(meeting_id,source_key));
CREATE INDEX segments_timeline ON transcript_segments(meeting_id,source_start_ms,user_id,segment_id) WHERE canonical;
CREATE TABLE transcript_drafts (segment_id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, user_id text NOT NULL, source_key text NOT NULL, body jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,source_key));
CREATE TABLE segment_versions (segment_id uuid NOT NULL REFERENCES transcript_segments(segment_id) ON DELETE CASCADE, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, valid_from integer NOT NULL, valid_to integer, raw_text text NOT NULL, body jsonb NOT NULL, PRIMARY KEY(segment_id,valid_from));
CREATE TABLE segment_replacements (meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, previous_id uuid NOT NULL, replacement_id uuid NOT NULL, transcript_version integer NOT NULL, PRIMARY KEY(previous_id,replacement_id));
CREATE TABLE coverage_gaps (id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, body jsonb NOT NULL);
CREATE TABLE meeting_markers (id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, body jsonb NOT NULL);
CREATE TABLE audio_chunks (id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, user_id text NOT NULL, start_ms integer NOT NULL, end_ms integer NOT NULL, storage_ref text NOT NULL, checksum text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', UNIQUE(meeting_id,user_id,start_ms,end_ms));
CREATE TABLE stt_streams (id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, user_id text NOT NULL, offset_ms integer NOT NULL, fencing bigint NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE summaries (id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, transcript_version integer NOT NULL, summary_version integer NOT NULL, prompt_hash text NOT NULL, model text NOT NULL, result jsonb NOT NULL, partial boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,transcript_version,prompt_hash,model), UNIQUE(meeting_id,summary_version));
CREATE TABLE jobs (id uuid PRIMARY KEY, key text NOT NULL UNIQUE, kind text NOT NULL, meeting_id uuid REFERENCES meetings(id) ON DELETE CASCADE, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, due_at timestamptz NOT NULL DEFAULT now(), owner text, lease_until timestamptz, generation integer NOT NULL DEFAULT 0, provider_job_id text, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_due ON jobs(due_at) WHERE status IN ('PENDING','RUNNING');
CREATE TABLE durable_timers (id uuid PRIMARY KEY, entity_id uuid NOT NULL, guild_id text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'PENDING', generation integer NOT NULL DEFAULT 0, owner text, lease_until timestamptz, UNIQUE(entity_id,kind));
CREATE TABLE outbox (id uuid PRIMARY KEY, entity_id uuid NOT NULL, guild_id text NOT NULL, kind text NOT NULL, revision integer NOT NULL, channel_id text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', message_id text, owner text, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), error_code text, UNIQUE(entity_id,kind,revision));
CREATE TABLE processed_interactions (interaction_id text PRIMARY KEY, guild_id text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_sessions (id_hash text PRIMARY KEY, user_id text NOT NULL, display_name text NOT NULL, tokens text NOT NULL, expires_at timestamptz NOT NULL, auth_cache jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states (state_hash text PRIMARY KEY, browser_hash text NOT NULL, return_to text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE glossary_versions (guild_id text NOT NULL, version integer NOT NULL, entries jsonb NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guild_id,version));
CREATE TABLE usage_records (id uuid PRIMARY KEY, guild_id text NOT NULL, meeting_id uuid, request_key text NOT NULL UNIQUE, provider text NOT NULL, audio_ms bigint NOT NULL DEFAULT 0, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cost_krw numeric NOT NULL DEFAULT 0, is_mock boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY, guild_id text NOT NULL, meeting_id uuid, actor text, kind text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deletion_tombstones (meeting_id uuid PRIMARY KEY, guild_id text NOT NULL, deleted_at timestamptz NOT NULL DEFAULT now(), cleaned_at timestamptz);
CREATE TABLE health_records (service text PRIMARY KEY, instance_id text NOT NULL, heartbeat_at timestamptz NOT NULL, metrics jsonb NOT NULL DEFAULT '{}');
